data class NativeGeoTiffInfo(val width:Int,val height:Int,val epsg:Int,val bounds:List<Double>,val detail:String,val affine:List<Double>)
data class NativeGeoTiffRaster(val width:Int,val height:Int,val samples:Int,val rgba:ByteArray,val epsg:Int,val affine:List<Double>,val bounds:List<Double>,val noData:Double?)

/** Classic GeoTIFF raster reader. It honors the declared CRS and affine georeference. */
object NativeGeoTiff {
 private data class Field(val type:Int,val count:Int,val valueOffset:Int,val inline:Int)
 private data class Tiff(val bytes:ByteArray,val order:ByteOrder,val fields:Map<Int,Field>) {
  fun size(type:Int)=when(type){1,2,6,7->1;3,8->2;4,9,11->4;5,10,12->8;else->error("TIFF字段类型不受支持")}
  fun values(tag:Int):DoubleArray {val f=fields[tag]?:error("GeoTIFF缺少标签$tag");val sz=size(f.type);val offset=if(sz*f.count<=4)f.valueOffset else f.inline;val bb=ByteBuffer.wrap(bytes).order(order);return DoubleArray(f.count){i->val p=offset+i*sz;when(f.type){1,2,6,7->(bytes[p].toInt() and 255).toDouble();3->(bb.getShort(p).toInt() and 65535).toDouble();8->bb.getShort(p).toDouble();4->(bb.getInt(p).toLong() and 0xffffffffL).toDouble();9->bb.getInt(p).toDouble();11->bb.getFloat(p).toDouble();12->bb.getDouble(p);5,10->{val den=(bb.getInt(p+4).toLong() and 0xffffffffL).toDouble();if(den==0.0)Double.NaN else (bb.getInt(p).toLong() and 0xffffffffL).toDouble()/den};else->error("TIFF字段类型错误")}}}
  fun scalar(tag:Int,default:Double=Double.NaN)=fields[tag]?.let{values(tag).first()}?:default
 }
 private data class Layout(val width:Int,val height:Int,val samples:Int,val bits:Int,val sampleFormat:Int,val compression:Int,val predictor:Int,val tiled:Boolean,val blockWidth:Int,val blockHeight:Int,val offsets:IntArray,val byteCounts:IntArray,val epsg:Int,val crs:NativeProjectCrs,val affine:List<Double>,val noData:Double?,val photo:Int,val tiff:Tiff)
 fun inspect(file:File):NativeGeoTiffInfo {val l=layout(file);val bounds=bounds(l);val compressed=if(l.compression==1)"未压缩" else "压缩${l.compression}";val tiling=if(l.tiled)"分块" else "条带";return NativeGeoTiffInfo(l.width,l.height,l.epsg,bounds,"EPSG:${l.epsg} · ${tiling}${compressed} · ${l.width}×${l.height}",l.affine)}
 fun load(file:File):NativeGeoTiffRaster {val l=layout(file);require(l.width.toLong()*l.height*4<=64L*1024*1024){"GeoTIFF显示副本超过64MiB"};val mins=DoubleArray(l.samples){Double.POSITIVE_INFINITY};val maxs=DoubleArray(l.samples){Double.NEGATIVE_INFINITY};val missing=ByteArray(l.width*l.height)
  visitSamples(l){x,y,c,v->if(v.isFinite()){if(isNoData(v,l.noData))missing[y*l.width+x]=(missing[y*l.width+x]+1).toByte() else {mins[c]=min(mins[c],v);maxs[c]=max(maxs[c],v)}}}
  require(mins.all{it.isFinite()}&&maxs.all{it.isFinite()}){"GeoTIFF没有可显示像素"};val rgba=ByteArray(l.width*l.height*4)
  visitSamples(l){x,y,c,v->if(v.isFinite()&&!isNoData(v,l.noData)){val o=(y*l.width+x)*4;when{l.samples==1->{val color=scale(v,mins[0],maxs[0]);val value=if(l.photo==0)255-color else color;rgba[o]=value.toByte();rgba[o+1]=value.toByte();rgba[o+2]=value.toByte();rgba[o+3]=0xff.toByte()};c<3->{rgba[o+c]=scale(v,mins[c],maxs[c]).toByte();if(c==0)rgba[o+3]=0xff.toByte()};c==3->rgba[o+3]=scaleAlpha(v,l).toByte()}}}
  if(l.noData!=null)for(i in missing.indices)if((missing[i].toInt() and 255)==l.samples)rgba[i*4+3]=0
  return NativeGeoTiffRaster(l.width,l.height,l.samples,rgba,l.epsg,l.affine,bounds(l),l.noData)
 }
 private fun scale(v:Double,minV:Double,maxV:Double):Int=if(!v.isFinite()||maxV<=minV)0 else (((v-minV)/(maxV-minV))*255.0).toInt().coerceIn(0,255)
 private fun scaleAlpha(v:Double,l:Layout):Int {val normalized=when{l.sampleFormat==3&&v in 0.0..1.0->v*255.0;l.bits==8->v;l.bits==16&&l.sampleFormat==1->v/65535.0*255.0;else->v};return normalized.toInt().coerceIn(0,255)}
 private fun isNoData(value:Double,noData:Double?)=noData!=null&&(value==noData||(value.isNaN()&&noData.isNaN()))
 private fun layout(file:File):Layout {require(file.length() in 8..NativeOfflineMapStore.MAX_FILE_BYTES){"GeoTIFF文件大小无效"};val bytes=file.readBytes();val order=when(String(bytes,0,2,Charsets.US_ASCII)){"II"->ByteOrder.LITTLE_ENDIAN;"MM"->ByteOrder.BIG_ENDIAN;else->error("GeoTIFF字节序无效")};val bb=ByteBuffer.wrap(bytes).order(order);require(bb.getShort(2).toInt()==42){"仅支持经典GeoTIFF，不支持BigTIFF"};val ifd=bb.getInt(4);require(ifd>=8&&ifd+2<=bytes.size);val count=bb.getShort(ifd).toInt() and 65535;require(count in 1..512&&ifd+2L+count*12L<=bytes.size);val fields=mutableMapOf<Int,Field>();for(i in 0 until count){val p=ifd+2+i*12;val tag=bb.getShort(p).toInt() and 65535;val type=bb.getShort(p+2).toInt() and 65535;val n=bb.getInt(p+4).toLong() and 0xffffffffL;require(n in 1..1_000_000);val size=when(type){1,2,6,7->1;3,8->2;4,9,11->4;5,10,12->8;else->error("TIFF字段类型不受支持")};val offset=bb.getInt(p+8);val inline=size*n<=4;val valueOffset=if(inline)p+8 else offset;val valueBytes=if(inline)size*n else 0L;require(valueOffset>=0&&valueOffset.toLong()+valueBytes<=bytes.size.toLong());if(!inline)require(offset.toLong()+size*n<=bytes.size.toLong());fields[tag]=Field(type,n.toInt(),valueOffset,offset)}
  val t=Tiff(bytes,order,fields);val width=t.scalar(256).toInt();val height=t.scalar(257).toInt();require(width in 2..16000&&height in 2..16000&&width.toLong()*height<=16_000_000){"GeoTIFF最多支持1600万像素"};val samples=t.scalar(277,1.0).toInt();require(samples in setOf(1,3,4)){"GeoTIFF支持灰度/RGB/RGBA"};val bits=t.values(258).map{it.toInt()}.distinct().single();require(bits in setOf(8,16,32)){"GeoTIFF只支持8/16位整数与32位浮点可视化"};val sampleFormat=t.scalar(339,1.0).toInt();require((bits==32&&sampleFormat==3)||(bits in setOf(8,16)&&sampleFormat in setOf(1,2))){"GeoTIFF采样类型不支持"};require(t.scalar(284,1.0).toInt()==1){"暂不支持平面分离的TIFF通道"};val photo=t.scalar(262).toInt();require((samples==1&&photo in setOf(0,1))||(samples>=3&&photo==2)){"GeoTIFF色彩通道不匹配"};val compression=t.scalar(259,1.0).toInt();require(compression in setOf(1,5,8,32946,32773)){"GeoTIFF压缩方式不支持"};val predictor=t.scalar(317,1.0).toInt();require(predictor in setOf(1,2)&&!(predictor==2&&sampleFormat==3)){"GeoTIFF Predictor 不支持"};require(t.scalar(274,1.0).toInt()==1){"GeoTIFF方向须为北向上"}
  val geokeys=t.values(34735).map{it.toInt()};require(geokeys.size>=4&&geokeys[0]==1);var epsg=0;for(i in 0 until geokeys[3]){val p=4+i*4;require(p+3<geokeys.size);if(geokeys[p+1]==0&&geokeys[p] in setOf(2048,3072))epsg=geokeys[p+3]};require(epsg>0){"GeoTIFF缺少明确EPSG GeoKey"};val crs=NativeCoordinateTransform.resolve("EPSG:$epsg");val rasterType=(0 until geokeys[3]).firstNotNullOfOrNull{i->val p=4+i*4;if(geokeys[p]==1025&&geokeys[p+1]==0)geokeys[p+3] else null};require(rasterType==1){"GeoTIFF必须是PixelIsArea，PixelIsPoint不能按区域影像显示"}
  val affine=if(fields.containsKey(34264)){val m=t.values(34264);require(m.size>=16&&m.all{it.isFinite()});require(abs(m[2])<1e-12&&abs(m[6])<1e-12&&abs(m[8])<1e-12&&abs(m[9])<1e-12&&abs(m[10]-1)<1e-12&&abs(m[11])<1e-12&&abs(m[12])<1e-12&&abs(m[13])<1e-12&&abs(m[14])<1e-12&&abs(m[15]-1)<1e-12){"GeoTIFF仿射矩阵包含透视/垂直分量，无法作为平面影像显示"};listOf(m[0],m[1],m[3],m[4],m[5],m[7])}else{val s=t.values(33550);val tie=t.values(33922);require(s.size>=2&&tie.size>=6&&s[0]>0&&s[1]>0&&tie.all{it.isFinite()}){"GeoTIFF缺少ModelPixelScale/ModelTiepoint配准"};listOf(s[0],0.0,tie[3]-tie[0]*s[0],0.0,-s[1],tie[4]+tie[1]*s[1])};require((affine[0]*affine[4]-affine[1]*affine[3]).let{it.isFinite()&&abs(it)>1e-20}){"GeoTIFF仿射配准矩阵无效"}
  val tiled=fields.containsKey(322);val blockW=if(tiled)t.scalar(322).toInt() else width;val blockH=if(tiled)t.scalar(323).toInt() else t.scalar(278,height.toDouble()).toInt();require(blockW>0&&blockH>0&&blockW<=width.coerceAtLeast(blockW)&&blockH<=height.coerceAtLeast(blockH));val offsets=t.values(if(tiled)324 else 273).map{it.toLong()};val byteCounts=t.values(if(tiled)325 else 279).map{it.toLong()};val across=(width+blockW-1)/blockW;val down=(height+blockH-1)/blockH;require(offsets.size==byteCounts.size&&offsets.size==across*down&&offsets.size<=100000){"GeoTIFF条带/分块目录无效"};require(offsets.indices.all{offsets[it]>=0&&byteCounts[it]>=0&&offsets[it]+byteCounts[it]<=bytes.size&&byteCounts[it]<=NativeOfflineMapStore.MAX_FILE_BYTES})
  val noData=fields[42113]?.let{f->String(bytes,f.valueOffset,f.count,Charsets.US_ASCII).trim('\u0000').toDoubleOrNull()};return Layout(width,height,samples,bits,sampleFormat,compression,predictor,tiled,blockW,blockH,offsets.map{it.toInt()}.toIntArray(),byteCounts.map{it.toInt()}.toIntArray(),epsg,crs,affine,noData,photo,t)
 }
 private fun visitSamples(l:Layout,visit:(Int,Int,Int,Double)->Unit){val bytes=l.tiff.bytes;val bytePerSample=l.bits/8;val across=(l.width+l.blockWidth-1)/l.blockWidth
  for(block in l.offsets.indices){val blockX=if(l.tiled)block%across else 0;val blockY=if(l.tiled)block/across else block;val startX=blockX*l.blockWidth;val startY=blockY*l.blockHeight;val cols=min(l.blockWidth,l.width-startX);val rows=min(l.blockHeight,l.height-startY);val decodedRows=if(l.tiled)l.blockHeight else rows;val encoded=bytes.copyOfRange(l.offsets[block],l.offsets[block]+l.byteCounts[block]);val nominalLong=l.blockWidth.toLong()*decodedRows*l.samples*bytePerSample;require(nominalLong in 1..NativeOfflineMapStore.MAX_FILE_BYTES){"GeoTIFF解压块超过64MiB"};val nominal=nominalLong.toInt();val raw=decompress(encoded,l.compression,nominal);val rowStride=l.blockWidth*l.samples*bytePerSample;require(raw.size>=rowStride*decodedRows){"GeoTIFF解压条带长度不足"};if(l.predictor==2)undoPredictor(raw,l, decodedRows,rowStride)
   for(y in 0 until rows)for(x in 0 until cols)for(c in 0 until l.samples){val p=y*rowStride+(x*l.samples+c)*bytePerSample;val v=sample(raw,p,l);visit(startX+x,startY+y,c,v)}
  }
 }
 private fun sample(b:ByteArray,p:Int,l:Layout):Double {val bb=ByteBuffer.wrap(b).order(l.tiff.order);return when(l.bits){8->if(l.sampleFormat==1)(b[p].toInt() and 255).toDouble() else b[p].toDouble();16->if(l.sampleFormat==1)(bb.getShort(p).toInt() and 65535).toDouble() else bb.getShort(p).toDouble();32->bb.getFloat(p).toDouble();else->Double.NaN}}
 private fun undoPredictor(raw:ByteArray,l:Layout,rows:Int,rowStride:Int){val bytes=l.bits/8;for(y in 0 until rows)for(i in l.samples until l.blockWidth*l.samples){val p=y*rowStride+i*bytes;val prior=p-l.samples*bytes;if(bytes==1)raw[p]=(raw[p].toInt()+raw[prior].toInt()).toByte()else if(bytes==2){val bb=ByteBuffer.wrap(raw).order(l.tiff.order);bb.putShort(p,(bb.getShort(p).toInt()+bb.getShort(prior).toInt()).toShort())}else{val bb=ByteBuffer.wrap(raw).order(l.tiff.order);bb.putInt(p,bb.getInt(p)+bb.getInt(prior))}}}
 private fun decompress(input:ByteArray,method:Int,expected:Int):ByteArray {val out=when(method){1->input;32773->packBits(input,expected);5->lzw(input,expected);8,32946->inflate(input,expected);else->error("GeoTIFF压缩不支持")};require(out.size>=expected){"GeoTIFF压缩条带数据不完整"};return out}
 private fun packBits(input:ByteArray,expected:Int):ByteArray {val out=ByteArrayOutputStream(expected);var i=0;while(i<input.size&&out.size()<expected){val n=input[i++].toInt();if(n in 0..127){val count=n+1;require(i+count<=input.size);out.write(input,i,count);i+=count}else if(n in -127..-1){require(i<input.size);val value=input[i++];repeat(1-n){out.write(value.toInt())}}};require(out.size()<=expected);return out.toByteArray()}
 private fun inflate(input:ByteArray,expected:Int):ByteArray {for(raw in listOf(false,true)){val inflater=Inflater(raw);try{inflater.setInput(input);val out=ByteArrayOutputStream(min(expected,1024*1024));val b=ByteArray(16384);while(!inflater.finished()){val n=try{inflater.inflate(b)}catch(_:Exception){break};if(n==0){if(inflater.needsInput()||inflater.needsDictionary())break};require(out.size()+n<=expected){"GeoTIFF解压大小超出声明"};out.write(b,0,n)};if(inflater.finished())return out.toByteArray()}finally{inflater.end()}};error("GeoTIFF Deflate 数据损坏")}
 private fun lzw(input:ByteArray,expected:Int):ByteArray {val dict=ArrayList<ByteArray>(4096);fun reset(){dict.clear();repeat(256){dict.add(byteArrayOf(it.toByte()))};dict.add(byteArrayOf());dict.add(byteArrayOf())};reset();var bit=0;var codeSize=9;var previous:ByteArray?=null;val out=ByteArrayOutputStream(expected);fun readCode():Int?{if(bit+codeSize>input.size*8)return null;var value=0;repeat(codeSize){val pos=bit++;value=(value shl 1) or ((input[pos/8].toInt() ushr (7-pos%8)) and 1)};return value};while(true){val code=readCode()?:break;if(code==256){reset();codeSize=9;previous=null;continue};if(code==257)break;val entry=if(code<dict.size&&dict[code].isNotEmpty())dict[code]else if(code==dict.size&&previous!=null)previous+previous[0]else error("GeoTIFF LZW码流无效");require(out.size()+entry.size<=expected){"GeoTIFF LZW解压超限"};out.write(entry);if(previous!=null&&dict.size<4096){dict.add(previous+entry[0]);if(dict.size==(1 shl codeSize)-1&&codeSize<12)codeSize++};previous=entry};return out.toByteArray()}
 private fun bounds(l:Layout):List<Double>{val points=listOf(transform(l,0.0,0.0),transform(l,l.width.toDouble(),0.0),transform(l,0.0,l.height.toDouble()),transform(l,l.width.toDouble(),l.height.toDouble())).map{NativeCoordinateTransform.transform(it,l.crs)};require(points.all{it.size>=2&&it[0].isFinite()&&it[1].isFinite()});val b=listOf(points.minOf{it[0]},points.minOf{it[1]},points.maxOf{it[0]},points.maxOf{it[1]});require(b[0]>=-180&&b[2]<=180&&b[1]>=-85.051129&&b[3]<=85.051129&&b[0]<b[2]&&b[1]<b[3]){"GeoTIFF投影范围不可显示或跨日期变更线"};return b}
 fun sourceCoordinate(r:NativeGeoTiffRaster,pixelX:Double,pixelY:Double):List<Double>{val a=r.affine;return listOf(a[0]*pixelX+a[1]*pixelY+a[2],a[3]*pixelX+a[4]*pixelY+a[5])}
 private fun transform(l:Layout,x:Double,y:Double)=listOf(l.affine[0]*x+l.affine[1]*y+l.affine[2],l.affine[3]*x+l.affine[4]*y+l.affine[5])
}
